CREATE TABLE "MarketplacePayoutHold" ("id" TEXT PRIMARY KEY, "sellerId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "status" TEXT NOT NULL DEFAULT 'ACTIVE', "reason" TEXT NOT NULL, "expiresAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "releasedById" TEXT, "releasedAt" TIMESTAMP(3), "releaseReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MarketplacePayoutHold_sellerId_status_expiresAt_idx" ON "MarketplacePayoutHold"("sellerId","status","expiresAt");
CREATE INDEX "MarketplacePayoutHold_orderId_status_idx" ON "MarketplacePayoutHold"("orderId","status");
CREATE TABLE "MarketplaceReconciliationRun" ("id" TEXT PRIMARY KEY, "createdById" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'COMPLETED', "currency" TEXT NOT NULL DEFAULT 'INR', "debitTotal" DECIMAL(16,2) NOT NULL, "creditTotal" DECIMAL(16,2) NOT NULL, "balanced" BOOLEAN NOT NULL DEFAULT false, "exceptionCount" INTEGER NOT NULL DEFAULT 0, "summary" JSONB NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MarketplaceReconciliationRun_completedAt_idx" ON "MarketplaceReconciliationRun"("completedAt");
CREATE INDEX "MarketplaceReconciliationRun_balanced_completedAt_idx" ON "MarketplaceReconciliationRun"("balanced","completedAt");
